(function(){const a=document.body.dataset.cat,c=BLISS.catBySlug[a];if(!c)return;const e=BLISS.catProducts(a),s=[...e].sort((t,n)=>n.rating-t.rating||n.reviews-t.reviews).slice(0,4);s.length?document.getElementById("catBest").innerHTML=s.map(productCard).join(""):document.getElementById("catBestWrap").hidden=!0,document.getElementById("catAll").innerHTML=e.map(productCard).join(""),document.getElementById("catAllCount").textContent=e.length?`${e.length} product${e.length===1?"":"s"} across every ${c.name.toLowerCase()} category.`:"",document.getElementById("catEmpty").hidden=e.length>0;const d={bathroom:"Bath",kitchen:"Kitchen",appliances:"Appliances",lighting:"Lighting",furniture:"Furniture",outdoor:"Outdoor"},i=BLISS.catTrail(a)[0].slug,o=new Set(e.map(t=>t.brand).filter(t=>!/Collection$/.test(t)));BLISS.brands.filter(t=>(t.cats||[]).includes(d[i])).slice(0,14).forEach(t=>o.add(t.name));const r=[...o].map(t=>BLISS.brands.find(n=>n.name===t)||{name:t}).slice(0,14);r.length?document.getElementById("catBrands").innerHTML=r.map(t=>t.slug?`<a href="brand.html?b=${t.slug}">${esc(t.name)}</a>`:`<span>${esc(t.name)}</span>`).join(""):document.getElementById("catBrandsWrap").hidden=!0,syncWish()})();
